#include <stdio.h>
#define SQUARE_OBJ(x) x * x            /* 对象式宏：纯文本替换 */
#define SQUARE_SAFE(x) ((x) * (x))      /* 加括号避免运算符优先级破坏 */

int sq_func(int x) { return x * x; }   /* 函数版 */

int main(void) {
    int a = SQUARE_OBJ(2 + 1);          /* 展开为 2+1 * 2+1 */
    int b = SQUARE_SAFE(2 + 1);         /* 展开为 ((2+1)*(2+1)) */
    int c = sq_func(2 + 1);
    printf("SQUARE_OBJ(2+1)  = %d\n", a);
    printf("SQUARE_SAFE(2+1) = %d\n", b);
    printf("sq_func(2+1)     = %d\n", c);
    return 0;
}
